const char *i960_host_sym_name(u32 addr)
{
    unsigned i;
    for (i = 0; i < sizeof(i960_host_sym_table) / sizeof(i960_host_sym_table[0]); i++) {
        if (i960_host_sym_table[i].addr == addr)
            return i960_host_sym_table[i].name;
    }
    return 0;
}
